{
  "name": "Prior弧光灯快门",
  "name_en": "Prior Arc Lamp Shutter",
  "manufacturer": "Prior",
  "description": "用于控制Prior弧光灯照明光路的快门，在显微和光学实验中实现照明的开启、关闭与状态查询，以便允许或阻断光线照射样品。",
  "description_en": "A shutter used to control the illumination path of a Prior arc lamp. In microscopy and optical experiments, it is used to enable or block lamp light and to query the shutter state.",
  "actions": [
    {
      "action_name": "auto-IsOn",
      "description": "查询弧光灯快门是否处于开启状态。",
      "description_en": "Check whether the arc lamp shutter is open/on."
    },
    {
      "action_name": "auto-TurnOn",
      "description": "打开弧光灯快门，使照明光通过。",
      "description_en": "Open the arc lamp shutter to allow illumination to pass."
    },
    {
      "action_name": "auto-TurnOff",
      "description": "关闭弧光灯快门，阻断照明光。",
      "description_en": "Close the arc lamp shutter to block illumination."
    },
    {
      "action_name": "auto-GetName",
      "description": "获取设备名称。",
      "description_en": "Get the device name."
    }
  ],
  "tag_hints": [
    "arc lamp illumination",
    "shutter control",
    "microscopy light path",
    "optical illumination blocking",
    "Prior"
  ]
}

